import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { addToCart } from '../features/cartSlice';
import { useNavigate } from 'react-router-dom';
import ProductCard from '../components/ProductCard'; // Fixed import statement
import { 
  Container, 
  Typography, 
  TextField, 
  Grid, 
  Box,
  InputAdornment
} from '@mui/material';
 import SearchIcon from '@mui/icons-material/Search';

const products = [
  { 
    id: 1, 
    name: 'MacBook Pro', 
    price: 1299.99, 
    image: 'https://source.unsplash.com/random/800x600/?macbook',
    description: '13-inch, M2 chip, 8GB RAM, 256GB SSD'
  },
  { 
    id: 2, 
    name: 'iPhone 14 Pro', 
    price: 999.99, 
    image: 'https://source.unsplash.com/random/800x600/?iphone',
    description: '256GB, Dynamic Island, Pro Camera System'
  },
  { 
    id: 3, 
    name: 'Sony WH-1000XM4', 
    price: 349.99, 
    image: 'https://source.unsplash.com/random/800x600/?headphones',
    description: 'Wireless Premium Noise Canceling Headphones'
  },
  { 
    id: 4, 
    name: 'Apple Watch Series 8', 
    price: 399.99, 
    image: 'https://source.unsplash.com/random/800x600/?applewatch',
    description: 'GPS, Always-On Retina display, Health features'
  },
  {
    id: 5,
    name: 'iPad Air',
    price: 599.99,
    image: 'https://source.unsplash.com/random/800x600/?ipad',
    description: '10.9-inch, M1 chip, 64GB, Wi-Fi'
  },
  {
    id: 6,
    name: 'AirPods Pro',
    price: 249.99,
    image: 'https://source.unsplash.com/random/800x600/?airpods',
    description: '2nd generation, Active Noise Cancellation'
  }
];

function Home() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');

  const filteredProducts = products.filter(prod =>
    prod.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Typography 
        variant="h3" 
        component="h1" 
        gutterBottom 
        align="center"
        sx={{ 
          fontWeight: 'bold',
          mb: 4 
        }}
      >
        Featured Products
      </Typography>
      
      <Box sx={{ mb: 4, display: 'flex', justifyContent: 'center' }}>
        <TextField
          variant="outlined"
          placeholder="Search products..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
          sx={{ 
            width: '100%',
            maxWidth: 600,
            '& .MuiOutlinedInput-root': {
              borderRadius: 2
            }
          }}
        />
      </Box>

      <Grid container spacing={4}>
        {filteredProducts.length === 0 ? (
          <Grid item xs={12}>
            <Typography 
              variant="h6" 
              color="text.secondary" 
              align="center"
              sx={{ mt: 4 }}
            >
              No products found.
            </Typography>
          </Grid>
        ) : (
          filteredProducts.map(product => (
            <Grid item key={product.id} xs={12} sm={6} md={4}>
              <ProductCard
                product={product}
                onAddToCart={() => {
                  dispatch(addToCart({ ...product, quantity: 1 }));
                  navigate('/cart');
                }}
              />
            </Grid>
          ))
        )}
      </Grid>
    </Container>
  );
}

export default Home;
